-- Canonical Quran catalog/data repair generated from Git-tracked sources.
-- Idempotent: safe to apply to an empty or partially populated target project.

ALTER TABLE public.quran_reciters
  ADD COLUMN IF NOT EXISTS code text,
  ADD COLUMN IF NOT EXISTS base_url_template text,
  ADD COLUMN IF NOT EXISTS recitation_type text;

CREATE UNIQUE INDEX IF NOT EXISTS quran_reciters_code_unique ON public.quran_reciters(code);
CREATE UNIQUE INDEX IF NOT EXISTS quran_audio_surah_reciter_unique ON public.quran_audio(surah_id, reciter_id);

ON CONFLICT (id) DO UPDATE SET
  name_ar = EXCLUDED.name_ar, name_en = EXCLUDED.name_en, name_translation = EXCLUDED.name_translation,
  revelation_place = EXCLUDED.revelation_place, ayahs_count = EXCLUDED.ayahs_count, "order" = EXCLUDED."order", slug = EXCLUDED.slug;

ON CONFLICT (code) DO UPDATE SET
  name_ar = EXCLUDED.name_ar, name_en = EXCLUDED.name_en, base_url_template = EXCLUDED.base_url_template,
  recitation_type = EXCLUDED.recitation_type, metadata = EXCLUDED.metadata;

