4621-9292-b6209715ac1f","surah_id":69,"ayah_number":51,"text_ar":"وَإِنَّهُۥ لَحَقُّ ٱلْيَقِينِ","text_en":null,"audio_url":null,"text_uthmani":"وَإِنَّهُۥ لَحَقُّ ٱلْيَقِينِ","text_simple":"وَإِنَّهُۥ لَحَقُّ ٱلْيَقِينِ","page":568,"juz":29,"hizb":227,"rub":227,"sajda":false,"searchable":"'لَحَقُّ':2,5 'وَإِنَّهُۥ':1,4 'ٱلْيَقِينِ':3,6","created_at":"2026-06-10T02:41:32.145138+00:00","updated_at":"2026-06-10T02:51:07.159722+00:00"}]$$::jsonb) AS x(
  surah_id integer, ayah_number integer, text_ar text, text_en text, text_uthmani text, text_simple text,
  page integer, juz integer, hizb integer, rub integer, sajda boolean
)
ON CONFLICT (surah_id, ayah_number) DO UPDATE SET
  text_ar = EXCLUDED.text_ar, text_en = EXCLUDED.text_en, text_uthmani = EXCLUDED.text_uthmani,
  text_simple = EXCLUDED.text_simple, page = EXCLUDED.page, juz = EXCLUDED.juz, hizb = EXCLUDED.hizb,
  rub = EXCLUDED.rub, sajda = EXCLUDED.sajda, updated_at = now();

SELECT s.id, r.id, r.base_url_template || '/' || lpad(s.id::text, 3, '0') || '.mp3',
  'https://www.mp3quran.net/', now(), jsonb_build_object('source', 'mp3quran.net', 'reciter_code', r.code), 'external', 'audio/mpeg'
FROM public.quran_surahs s CROSS JOIN public.quran_reciters r
WHERE s.id BETWEEN 1 AND 114 AND r.code IS NOT NULL AND r.base_url_template IS NOT NULL
ON CONFLICT (surah_id, reciter_id) DO UPDATE SET
  audio_url = EXCLUDED.audio_url, source_url = EXCLUDED.source_url, metadata = EXCLUDED.metadata,
  storage_status = 'external', mime_type = 'audio/mpeg';
